import re
from flows2 import *
INK='#0D0F12'; LMUT='#5B6169'; LBD='#E4E6E9'; LS='#F5F6F7'
def bar(right):  # schmale Kopfzeile, Logo links
    return f'<tr><td style="padding:16px 20px;background:{BG};border-bottom:1px solid {BD};font-family:{F};"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="text-align:left;"><img src="{LOGO}" width="30" height="30" alt="" style="display:inline-block;vertical-align:middle;border:0;"><span style="display:inline-block;vertical-align:middle;margin-left:8px;font-size:12px;font-weight:800;letter-spacing:.3em;color:#E6E8EB;">PEPTRIUM</span></td><td style="text-align:right;font-size:11px;color:{DIM};">{right}</td></tr></table></td></tr>'
def chips():
    c=''.join(f'<td align="center" style="padding:0 3px;"><div style="border:1px solid {BD};border-radius:999px;padding:8px 6px;font-size:11px;font-weight:700;color:#D9DDE2;white-space:nowrap;font-family:{F};">{t}</div></td>' for t in ['✓ HPLC-geprüft','✓ Diskret','✓ 2 Werktage'])
    return f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>{c}</tr></table>'
# --- Warenkorb 1: kurz, Warenkorb zuerst, linksbündig ---
W1=body(bar('Dein Warenkorb')
 +row(f'<div style="text-align:left;"><div style="font-size:34px;line-height:1.08;font-weight:800;color:#FFF;letter-spacing:-.02em;">Dein Warenkorb<br>wartet noch.</div><div style="font-size:15px;line-height:1.55;color:{MUT};margin:12px 0 20px;">Wir haben alles für dich gespeichert. Mit einem Klick geht es genau dort weiter, wo du aufgehört hast.</div></div>'+items(CART,'156,70 €')+'<div style="height:16px;"></div>'+btn('Bestellung abschließen →','#')+'<div style="height:18px;"></div>'+chips(),'30px 20px 30px')
 +optout()+cfoot())
# --- Warenkorb 2: Fragen-Format, Kontakt im Mittelpunkt ---
def qa(n,q,a): return f'<tr><td width="40" valign="top" style="width:40px;padding:14px 0;"><div style="width:30px;height:30px;line-height:30px;border-radius:50%;background:#FFFFFF;color:#0D0F12;font-weight:800;font-size:14px;text-align:center;font-family:{F};">{n}</div></td><td style="padding:14px 4px;text-align:left;font-family:{F};border-bottom:1px solid {BD};"><div style="font-size:15px;font-weight:800;color:#FFF;">{q}</div><div style="font-size:13px;line-height:1.55;color:{MUT};margin-top:4px;">{a}</div></td></tr>'
thumbs=''.join(f'<td width="56" style="width:56px;padding-right:8px;"><img src="{i[0]}" width="48" height="48" style="display:block;border-radius:10px;border:0;"></td>' for i in CART)
W2=body(bar('Kurze Frage')
 +row(f'<div style="text-align:left;"><div style="font-size:34px;line-height:1.08;font-weight:800;color:#FFF;letter-spacing:-.02em;">Noch Fragen<br><span style="color:#8E959E;">vor dem Bestellen?</span></div><div style="font-size:15px;line-height:1.55;color:{MUT};margin:12px 0 6px;">Viele zögern beim ersten Mal – das verstehen wir. Hier die häufigsten Fragen:</div></div>'
   +'<table role="presentation" width="100%" cellpadding="0" cellspacing="0">'+qa(1,'Wie bezahle ich?','Per Vorkasse (Überweisung) oder Krypto. Nach Zahlungseingang geht dein Paket raus.')+qa(2,'Wie schnell kommt es an?','In der Regel innerhalb von 2 Werktagen per DHL, ab 100 € versandkostenfrei.')+qa(3,'Wie wird verpackt?','Neutral und diskret, ohne Hinweis auf den Inhalt.')+'</table>','30px 20px 22px')
 +row(f'<div style="border:1px solid {BD};background:{CARD};border-radius:18px;padding:20px 16px;"><div style="font-size:17px;font-weight:800;color:#FFF;margin-bottom:4px;">Frag uns direkt</div><div style="font-size:13px;color:{MUT};margin-bottom:14px;">Wir antworten meist innerhalb weniger Stunden.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="50%" style="padding-right:5px;"><a href="mailto:info@peptrium.com" style="display:block;background:#FFFFFF;color:#0D0F12;text-decoration:none;font-weight:800;font-size:14px;padding:13px 6px;border-radius:12px;text-align:center;">✉️ E-Mail</a></td><td width="50%" style="padding-left:5px;"><a href="https://t.me/peptrium" style="display:block;background:#229ED9;color:#FFFFFF;text-decoration:none;font-weight:800;font-size:14px;padding:13px 6px;border-radius:12px;text-align:center;">Telegram</a></td></tr></table></div>','0 20px 26px')
 +row(f'<div style="text-align:left;font-size:12px;font-weight:700;letter-spacing:.16em;color:{DIM};margin-bottom:10px;">DEIN WARENKORB · 156,70 €</div><table role="presentation" cellpadding="0" cellspacing="0"><tr>{thumbs}</tr></table><div style="height:16px;"></div>'+btn('Zum Warenkorb →','#'),'0 20px 30px')
 +optout()+re.sub(r'<div style="font-size:15px;font-weight:700;color:#FFFFFF;margin-bottom:12px;">Fragen\?.*?</table><div style="height:28px;"></div>','',cfoot(),flags=re.S))
# --- Nach der Lieferung: HELL (Service, keine Werbung), Checkliste ---
def lrow(inner,pad='26px 20px',bg='#FFFFFF',al='left'): return f'<tr><td style="padding:{pad};background:{bg};text-align:{al};font-family:{F};color:{INK};">{inner}</td></tr>'
def step(n,t,d,link,lt): return f'<tr><td width="44" valign="top" style="width:44px;padding:14px 0;"><div style="width:32px;height:32px;line-height:32px;border-radius:50%;background:{INK};color:#FFF;font-weight:800;font-size:14px;text-align:center;">{n}</div></td><td style="padding:14px 4px;border-bottom:1px solid {LBD};"><div style="font-size:16px;font-weight:800;color:{INK};">{t}</div><div style="font-size:13px;line-height:1.55;color:{LMUT};margin:3px 0 6px;">{d}</div>'+(f'<a href="{link}" style="font-size:13px;font-weight:700;color:{INK};">{lt} →</a>' if link else '')+'</td></tr>'
litems=''.join(f'<td width="50%" valign="top" style="width:50%;padding:5px;"><div style="border:1px solid {LBD};border-radius:14px;overflow:hidden;background:#FFF;"><img src="{i[0]}" width="150" style="display:block;width:100%;height:auto;border:0;"><div style="padding:10px;"><div style="font-size:14px;font-weight:800;color:{INK};">{i[1]}</div><div style="font-size:12px;color:{LMUT};">{i[2]}</div></div></div></td>' for i in CART)
NL=('<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#E9EBED;"><tr><td align="center"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#FFFFFF;">'
 +bar('Bestellung #3243')
 +lrow(f'<div style="font-size:12px;font-weight:700;letter-spacing:.16em;color:{LMUT};">📦 ZUGESTELLT</div><div style="font-size:32px;line-height:1.1;font-weight:800;color:{INK};margin:8px 0 10px;letter-spacing:-.02em;">Ist alles gut<br>angekommen?</div><div style="font-size:15px;line-height:1.55;color:{LMUT};">Deine Bestellung sollte inzwischen bei dir sein. Damit deine Forschung gut startet, hier 3 kurze Punkte.</div>','30px 20px 10px')
 +lrow('<table role="presentation" width="100%" cellpadding="0" cellspacing="0">'+step(1,'Lieferung prüfen','Stimmt alles? Falls etwas fehlt oder beschädigt ist, melde dich – wir kümmern uns sofort.','mailto:info@peptrium.com','Problem melden')+step(2,'Richtig lagern','Lyophilisierte Peptide kühl und dunkel, gelöste im Kühlschrank.','https://peptrium.com/lagerungs-guide/','Lagerungs-Guide')+step(3,'Exakt rekonstituieren','Der Peptid-Rechner zeigt dir die passende Menge Bac Water.','https://peptrium.com/peptid-rechner/','Peptid-Rechner')+'</table>','6px 20px 24px')
 +lrow(f'<div style="font-size:12px;font-weight:700;letter-spacing:.16em;color:{LMUT};margin-bottom:8px;">DEINE BESTELLUNG</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 -5px;width:calc(100% + 10px);"><tr>{litems}</tr></table><div style="height:16px;"></div><a href="#" style="display:block;background:#FFF;color:{INK};border:1.5px solid {INK};text-align:center;text-decoration:none;font-weight:800;font-size:15px;padding:14px;border-radius:12px;">Erneut bestellen</a>','10px 20px 30px',LS)
 +'</table></td></tr></table>')
NL=NL.replace('</table></td></tr></table>', '')+foot().replace('weil du den Peptrium-Newsletter abonniert hast','weil du bei Peptrium bestellt hast')+'</table></td></tr></table>'
for k,v in {'v_warenkorb1':W1,'v_warenkorb2':W2,'v_nachlieferung':NL}.items(): open(k+'.html','w').write(f'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:{BG};">{v}</body></html>')
